from pysat.solvers import Glucose4
from pysat.card import CardEnc
import collections

def solve():
    n = 24
    E = 33

    solver = Glucose4()

    def edge_var(i, j):
        if i > j: i, j = j, i
        return i * n + j + 1

    # 3-colorable
    color_var_offset = n * n + 1
    def color_var(i, k):
        return color_var_offset + i * 3 + k

    for i in range(n):
        solver.add_clause([color_var(i, 0), color_var(i, 1), color_var(i, 2)])
        solver.add_clause([-color_var(i, 0), -color_var(i, 1)])
        solver.add_clause([-color_var(i, 0), -color_var(i, 2)])
        solver.add_clause([-color_var(i, 1), -color_var(i, 2)])

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(3):
                solver.add_clause([-edge_var(i, j), -color_var(i, k), -color_var(j, k)])

    # Max degree 3
    for i in range(n):
        adj_vars = []
        for j in range(n):
            if i != j:
                adj_vars.append(edge_var(i, j))
        clauses = CardEnc.atmost(lits=adj_vars, bound=3, vpool=None, encoding=1)
        for clause in clauses:
            solver.add_clause(clause)

    # At least E edges
    edge_vars = [edge_var(i, j) for i in range(n) for j in range(i + 1, n)]
    clauses = CardEnc.atleast(lits=edge_vars, bound=E, vpool=None, encoding=1)
    for clause in clauses:
        solver.add_clause(clause)

    def find_all_short_cycles(edges):
        adj = collections.defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        cycles = []
        for i in range(n):
            q = collections.deque([(i, -1, 0)])
            visited = {i: 0}
            parent = {i: -1}
            while q:
                curr, p, dist = q.popleft()
                if dist >= 3:
                    continue
                for nxt in adj[curr]:
                    if nxt == p:
                        continue
                    if nxt in visited:
                        if visited[nxt] >= dist: # to avoid duplicates and only find cycles <= 6
                            cycle_len = dist + visited[nxt] + 1
                            if cycle_len <= 6:
                                path1 = []
                                curr1 = curr
                                while curr1 != -1:
                                    path1.append(curr1)
                                    curr1 = parent[curr1]
                                path1.reverse()

                                path2 = []
                                curr2 = nxt
                                while curr2 != -1:
                                    path2.append(curr2)
                                    curr2 = parent[curr2]
                                path2.reverse()

                                lca_idx = 0
                                while lca_idx < len(path1) and lca_idx < len(path2) and path1[lca_idx] == path2[lca_idx]:
                                    lca_idx += 1
                                lca_idx -= 1

                                cycle = path1[lca_idx:] + path2[lca_idx:][::-1]
                                # normalize cycle
                                min_idx = cycle.index(min(cycle))
                                if cycle[(min_idx + 1) % len(cycle)] > cycle[(min_idx - 1) % len(cycle)]:
                                    cycle = cycle[min_idx:] + cycle[:min_idx]
                                else:
                                    cycle = cycle[min_idx::-1] + cycle[:min_idx:-1]
                                cycles.append(tuple(cycle))
                    else:
                        visited[nxt] = dist + 1
                        parent[nxt] = curr
                        q.append((nxt, curr, dist + 1))
        return list(set(cycles))

    iteration = 0
    while True:
        iteration += 1
        if solver.solve():
            model = solver.get_model()
            edges = []
            for i in range(n):
                for j in range(i + 1, n):
                    if model[edge_var(i, j) - 1] > 0:
                        edges.append((i, j))

            cycles = find_all_short_cycles(edges)
            if not cycles:
                print("Found graph!")
                print(edges)
                break
            else:
                for cycle in cycles:
                    clause = []
                    for k in range(len(cycle)):
                        u = cycle[k]
                        v = cycle[(k + 1) % len(cycle)]
                        clause.append(-edge_var(u, v))
                    solver.add_clause(clause)
                if iteration % 10 == 0:
                    print(f"Iteration {iteration}, added {len(cycles)} clauses")
        else:
            print("UNSAT")
            break

solve()

